mapper.insert:
INSERT INTO anime_character (
    mal_id, anilist_id, name, name_jp, image_url, about, nicknames, birthday, favorites, created_at, updated_at
) VALUES (
    #{malId}, #{anilistId}, #{name}, #{nameJp}, #{imageUrl}, #{about}, #{nicknames}, #{birthday}, #{favorites}, NOW(), NOW()
)

mapper.select:
SELECT ac.id, ac.mal_id, ac.anilist_id, ac.name, ac.name_jp, ac.image_url, ac.favorites, COALESCE(ufc.favorite_status, 0) AS isLiked FROM anime_character ac LEFT JOIN user_favorite_character ufc ON ac.id = ufc.character_id AND ufc.user_id = #{userId}
AND (ac.name LIKE CONCAT('%', #{name}, '%') OR ac.name_jp LIKE CONCAT('%', #{name}, '%'))
ORDER BY ac.favorites DESC, ac.id ASC
